        val c = comb(n, k)
        val term = c * c % MOD
        term = term * fact[k] % MOD
        term = term * fact[n - k] % MOD
        ans = (ans + term) % MOD
    }
    ans = ans * inv[2] % MOD
    println(ans)
}
