    val dp = LongArray(n + 1)
    dp[0] = 1
    for (i in 1..n) {
        dp[i] = dp[i - 1]
        if (i >= 2) {
            dp[i] = (dp[i] + dp[i - 2] * (i - 1)) % MOD
        }
    }
    var ans = 0L
    for (k in 0..n) {
        val c = comb(n, k, dp)
        val term = c * dp[n - k] % MOD
        term * (if (k % 2 == 0) 1 else -1)
        ans = (ans + term * (if (k % 2 == 0) 1 else MOD - 1)) % MOD
    }
    ans = ans * dp[n] % MOD
    ans = (ans % MOD + MOD) % MOD
    println(ans)
}

fun comb(n: Int, k: Int, dp: LongArray): Long {
    if (k < 0 || k > n) return 0
    var res = 1L
    for (i in 0 until k) {
        res = res * (n - i) % MOD
        res = res * modInv(i + 1L, MOD) % MOD
    }
    return res
}

fun modInv(a: Long, mod: Long): Long {
    var a = a
    var m = mod
    var x = 0L
    var y = 1L
    while (a > 1) {
        val q = a / m
        var temp = m
        m = a % m
        a = temp
        temp = x
        x = y - q * x
        y = temp
    }
    if (y < 0) y += mod
    return y
}
